// Presentation metadata for the brief's sections. The time
// budgets and the "what this replaced" mapping are FIXED here in the UI layer,
// not generated by the model — they are deterministic facts about the reading
// experience, so they don't belong in the LLM output.
//
// Two totals make the value proposition literal:
//   • readSeconds sum to 300 → the "5:00" cumulative meter in the rail.
//   • replacesMinutes sum to 45 → the old manual-prep routine this replaces.

export interface SectionMeta {
  /** Anchor id — matches the rendered <section id> and the brief field. */
  id: string;
  label: string;
  /** Reading budget for the "5:00" meter, in seconds. */
  readSeconds: number;
  /** The manual step this section replaces, and roughly how long it took. */
  replacesLabel: string;
  replacesMinutes: number;
}

export const SECTIONS: SectionMeta[] = [
  { id: "tldr", label: "TL;DR", readSeconds: 20, replacesLabel: "skimming the account to form a first take", replacesMinutes: 3 },
  { id: "room", label: "Who's in the room", readSeconds: 35, replacesLabel: "cross-referencing the invite against CRM and LinkedIn", replacesMinutes: 6 },
  { id: "dealState", label: "Deal state", readSeconds: 25, replacesLabel: "clicking through the Salesforce opp and activity", replacesMinutes: 4 },
  { id: "lastConversation", label: "Last conversation", readSeconds: 40, replacesLabel: "re-listening to the intro call", replacesMinutes: 12 },
  { id: "whyNow", label: "Why now", readSeconds: 25, replacesLabel: "searching the web for company news", replacesMinutes: 5 },
  { id: "buriedAlpha", label: "Buried alpha", readSeconds: 20, replacesLabel: "the insight you'd usually miss entirely", replacesMinutes: 0 },
  { id: "hypothesizedPains", label: "Hypothesized pains", readSeconds: 35, replacesLabel: "forming a point of view from scattered notes", replacesMinutes: 5 },
  { id: "proofPoints", label: "Proof points", readSeconds: 30, replacesLabel: "hunting the knowledge base for a relevant case study", replacesMinutes: 4 },
  { id: "askThese", label: "Ask these", readSeconds: 35, replacesLabel: "drafting discovery questions from scratch", replacesMinutes: 4 },
  { id: "landmines", label: "Landmines", readSeconds: 25, replacesLabel: "usually discovered live, in the room", replacesMinutes: 2 },
  { id: "unknowns", label: "What we don't know", readSeconds: 10, replacesLabel: "usually not done at all", replacesMinutes: 0 },
];

export const TOTAL_READ_SECONDS = SECTIONS.reduce((n, s) => n + s.readSeconds, 0); // 300
export const TOTAL_REPLACED_MINUTES = SECTIONS.reduce((n, s) => n + s.replacesMinutes, 0); // 45

export function formatSeconds(total: number): string {
  const m = Math.floor(total / 60);
  const s = Math.round(total % 60);
  return `${m}:${String(s).padStart(2, "0")}`;
}

export function sectionMeta(id: string): SectionMeta | undefined {
  return SECTIONS.find((s) => s.id === id);
}
